#!/usr/bin/env python3
"""Terminal documents from frozen actual analysis/review; never execute physics."""
import pathlib,json,gzip,datetime,hashlib
R=pathlib.Path(__file__).resolve().parents[2];D=R/'outer/c006'
def read(p):return json.loads((R/p).read_text())
def write(p,x):(R/p).write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n')
def sha(p):return hashlib.sha256((R/p).read_bytes()).hexdigest()
a=read('outer/c006/analysis.json');review=read('outer/c006/final-review.json');before=read('outer/c006/accepted-before.json');now=datetime.datetime.now(datetime.timezone.utc).isoformat();risk=read('outer/c006/risk/c006-risk-results.json')
passed=a['complete'] and all(a['criteria'].values()) and not review.get('scientificBlockers',[])
if not a['complete']:assert (D/'early-stop.json').exists(),'Partial terminal requires explicit unstarted slots and stopping reason'
status='conditional-adopt' if passed else 'reject';version='adaptive-general-carried-neighbor-macro-v1'
runs=[json.loads(gzip.decompress(p.read_bytes())) for p in sorted((R/'evidence/runs').glob('c006-*.json.gz'))];formal=[r for r in runs if r['pool']=='main'];local=[r for r in runs if r['pool']!='main']
def cost(rs):return{'physicalStarts':sum(r['physicalStarted'] for r in rs),'ticks':sum(r['ticks'] for r in rs),'substeps':sum(r['substeps'] for r in rs),'runnerWallSeconds':sum(r['wallSeconds'] for r in rs)}
pairs=a['pairs'];nparent=sum(p['parentQualified'] for p in pairs);ncandidate=sum(p['candidateQualified'] for p in pairs)
qualification='Finite24 paired non-none-neighbor conditions with both assigned routes; same cumulative prefix, actual complete auxiliary/core bodies, bridges/successor, typed order/recovery and saved action contrasts; current H/T/J/L plus changed-T obligations retained' if passed else 'No new accepted macro capability; preserve exact failed/incomplete scope and current accepted c005'
rule={'schema':'adaptive-general-c006-rule/1','status':status,'coverage':'complete' if a['complete'] else 'partial','version':version,'parent':before['version'],'generator':'source/neighbor-generator.cjs','config':'source/configs/neighbor-parent-binding.json','entrypoint':'compile(physicalCondition,{schema:"neighbor-late-macro-request/1",parentRequest,macro})','qualification':qualification,'domain':{'slots':[9,10],'pinned':[0,1,2,3,4,5,6,7,8,11],'adjacency':['upper-after','lower-before'],'inheritedForms':['B','H','T','J','HT','HJ','JT','HJT','L','HL','LT','HLT'],'parentRequest':'explicit accepted cumulative map with macro=null','newThemeScope':'request chooses existing primary pattern ordering; auxiliary bodies remain actual; no whole-image symmetry or new internal pattern claim'},'invariants':['all carried bodies retained and observed','unchanged body-expanded shrink and bridge guards','absolute phase correction without clock reset','same accepted prefix in both arms','L current route fingerprint explicitly rebound; old body/successor guard unchanged','current mapped pressure identity; no disappearance improvement','real tick0 and complete input/state evidence','no post-reveal narrowing, retuning or threshold changes'],'localRisk':{'separateHypothesis':True,'record':'outer/c006/risk/c006-risk-results.json','maxProbes':4,'baselineReused':True,'mapTuning':False,'macroVeto':False,'qualification':'four discrete source/receiver-window sensitivity observations only'},'unknown':['arbitrary dependencies or relocation','new internal geometry patterns','whole-image symmetry','continuous-neighborhood input robustness','natural route discovery','human fun']}
write('outer/c006/rule.json',rule)
gaps=read('GAPS.json')
for g in gaps:
 if g['id']=='macro-adjacency-extension':g.update(state='solved' if passed else 'still-present',scope='Finite request-controlled9/10 package order/recovery with all upper-after/lower-before carried bodies, current prefix and actual continuous evidence',evidence='outer/c006/analysis.json',adoption='pending durable close' if passed else 'rejected')
 if g['id']=='laser-tight-clearance-robustness':g.update(state='still-present',scope='Original1.199px witness retained; four discrete phase±0.1/y±3 local probes passed with changed inputs, not a continuous-neighborhood or player-tolerance certificate',evidence='outer/c006/risk/c006-risk-results.json',adoption='diagnostic evidence only; no map repair')
write('outer/c006/gap-results.json',gaps)
write('outer/c006/decision.json',{'schema':'adaptive-round-decision/1','round':'c006','status':status,'coverage':rule['coverage'],'decidedAt':now,'adopted':False,'adoptionGate':'successful independent raw archive before pointer; final source/progress save before durable close','version':version,'parent':before['version'],'acceptedVersionIfRejected':before['version'],'generator':rule['generator'],'decisionType':'finite carried-neighbor macro ability and actual request-expression expansion; separate bounded risk diagnosis','qualification':qualification,'criteria':a['criteria'],'analysis':'outer/c006/analysis.json','analysisSHA256':sha('outer/c006/analysis.json'),'review':'outer/c006/final-review.json','reviewSHA256':sha('outer/c006/final-review.json'),'nominalSlots':192,'formalSlots':len(formal),'unstartedSlots':192-len(formal),'localRiskSlots':len(local),'cost':cost(runs),'formalCost':cost(formal),'localRiskCost':cost(local),'cumulativeCost':a['cost'],'sourceFreeze':'protocols/freezes/c006-formal-v1.json','sourceManifestHash':a['sourceManifestHash'],'sourceIdentity':read('reports/c006-bound-static.json')['sourceIdentity'],'humanFun':None})
contrasts='\n'.join(f"- {q['a']}→{q['b']} / {q['role']}：{q['kind']}，实际顺序{q['orders']}，恢复{q['recoveryBeforeTicks']}/{q['recoveryAfterTicks']}ticks；命令改变{q['commandsChanged']}，最大真实y差{q['maximumYDifferencePx']:.3f}px；关系与请求对照合格{q['passed']}" for q in a['contrasts']) or '尚无完整同入口对照；不能补成通过。'
failures='\n'.join('- '+q['condition']+'/'+q['role']+': '+str(q.get('error') or {'parentQualified':q['parentQualified'],'candidateQualified':q['candidateQualified']}) for q in pairs if not(q['parentQualified'] and q['candidateQualified'])) or '已完成指定路线未发现资格失败。'
(D/'REPORT.zh-CN.md').write_text(f'''# c006：带邻体的真实编排、动作和恢复变化\n\n结论：{status}（{rule['coverage']}）。raw成功保存前不推进接受指针；最终累计源码/进度保存后才持久关闭。\n\n## 得到了什么\n\n候选把既有9/10完整包顺序和恢复请求延伸到upper-after/lower-before邻接。辅助体始终保留在真实地图、相位/身份变换、body-expanded边界及保存体观察中；primary识别视图分离辅助体不等于删去它。父/候选使用同一显式macro-null累计prefix。旧生成器对完整新邻接macro的拒绝另记，物理companion不冒充旧完整意图支持。\n\nL仅声明重绑当前全图路线hash，源、同侧接收、首需求和实际T后继保持原样；原L guard仍验证每臂当前图。没有新增物理、放宽桥或删改旧资格门。\n\n## 正式证据\n\n- 24条件请求计划192槽；已结算{len(formal)}，未启动{192-len(formal)}\n- 指定路线父/候选完整资格{nparent}/48、{ncandidate}/48；同图两角色相关，不是独立地图样本\n- 原75+20聚焦静态证据复用；最终仅重做16公开绑定。新留出在语义源码Library成功后一次生成，未重抽，也未重复c005已揭晓六字段物理组合\n- 第一8槽HLT/upper-after pilot计入正式面板；通过后立即继续，图与报告并行\n- 主面板成本：{cost(formal)}\n- 局部风险成本：{cost(local)}；没有重复风险基线或新codec\n\n## 同入口请求如何改变实际体验代理\n\n{contrasts}\n\n这些差异来自保存的真实输入与状态；图中的完整邻体、排列、全程/晚段净空及恢复曲线见visual-site-manifest-v1.json。压力成员通过原始到当前ID双射逐项保留，没有把消失的旧ID当改善。宽/窄或更多flap并不自动代表更好玩。\n\n主题只选择既有primary内部图案的顺序。上/下辅助体可打破整个画面的对称，因此不能把primary成对对称分数描述成整图对称，也没有创造新内部图案。\n\n## 独立薄余量支线\n\n复用已认证的c005 LT支路基线（活动胶囊最小余量1.199358px），四个预声明点均从真实tick0跑到1509tick源/接收/首需求窗口。phase−0.1、phase+0.1、y−3、y+3的实际最小余量分别9.636454、24.458811、24.559890、9.482428px，实际源窗口命令变化4/6/6/4个tick。\n\n四点都局部存活，不证明基线周围全部参数或输入时刻稳健；控制器改变输入后的非线性结果不可插值。phase还影响生成与其它机制，不是只对激光的隔离干预。后段未在这些prefix probes中重测；baseline完整记录仍保留。本轮不因此调参/放宽地图，不把支线当宏扩展自动否决，也不声称人类容错或公平性已经验证。\n\n## 失败、诊断与边界\n\n{failures}\n\nH1/H1-slow共{len(a['diagnostics'])}个独立诊断记录，{sum(bool(d.get('aliveHorizon')) for d in a['diagnostics'])}存活全程，{sum(bool(d.get('rawTaskPass')) for d in a['diagnostics'])}原指定任务通过；不混入指定路线成功率。未到达、缺失、删失与失败不补零。\n\n仅有限已测域可条件采用；任意搬移/新依赖、连续邻域稳健、自然路线发现、触控及真人乐趣仍未知。所有旧源、失败、原资格门和留出揭晓历史保留。\n''')
(D/'GENERATING-SKILL.zh-CN.md').write_text('''# 带辅助邻体的有限请求编排方法\n\n1. 显式绑定持久接受的累计prefix，并要求物理parentRequest产生macro-null地图。完整旧意图支持与另一个物理companion请求分别记录\n2. 在主动作识别中分离经过严格验证的辅助体，禁止在实际地图、边界、搬移或观察中省略它\n3. 只搬移完整9/10包，固定0–8/11，按实际全体身体/routeMark/checkpoint/bridge推导收缩界限，并保留60tick上限\n4. 相位按绝对世界时钟与位移修正；路线、时间表、压力身份和实际表达同步，精确反向构造必须恢复父图\n5. 全图route hash变化时，只对完全固定的L上下文作声明式当前哈希重绑定，保留前后来源，原guard不变\n6. 从真实tick0观察前驱、全部包体、邻体相对primary顺序、两桥以及slot11首需求和辅助体；当前可选机制与changed-T依旧要求实际证据\n7. 用同入口不同顺序/恢复请求的真实输入、状态和净空曲线检验表达；primary图案分数不等于含邻体整图对称，不能自称新内部模式\n8. 薄余量风险先复用见证、预注册少量单变量局部probe，单列诊断与未知；不自动调参或把四点通过称邻域认证\n9. 保留失败与全部槽分母，raw成功保存先于接受指针，最终累计源/进度保存先于关闭\n''')
write('outer/c006/terminal-facts.json',{'status':status,'coverage':rule['coverage'],'version':version,'cost':cost(runs),'formalCost':cost(formal),'localRiskCost':cost(local),'allCriteria':passed,'parentAssignedQualified':nparent,'candidateAssignedQualified':ncandidate,'qualifiedRequestContrasts':sum(q['passed'] for q in a['contrasts']),'decisionAt':now})
print(json.dumps({'status':status,'coverage':rule['coverage'],'formalSlots':len(formal),'localSlots':len(local),'cost':cost(runs)}))
